"""Non-normative preparation guidance when a legal conclusion cannot be verified.

Never uses the rejected draft, cites unread law, or promises a legal outcome.
"""
import re

COMMON='Соберите в одном месте уже имеющиеся документы и сообщения, запишите последовательность событий и желаемый результат. Отдельно отметьте факты, в которых вы не уверены.'
TOPICS={
    'land':'Для подготовки разбора участка удобно сопоставить его описание, имеющиеся документы и полученные уведомления. Разделите сведения из документов и то, что известно только со слов других людей.',
    'labor':'Для разбора ситуации на работе соберите договор, доступные расчётные сведения и переписку. Составьте список ожидаемых и фактически полученных выплат либо последовательность спорных событий.',
    'consumer':'Для подготовки обращения к продавцу соберите сведения о покупке, подтверждение оплаты, переписку и описание неисправности. Зафиксируйте, когда обнаружилась проблема и какого результата вы хотите: деньги, замена или устранение недостатка.',
    'housing':'Для разбора спора о жилье соберите договор или переписку об условиях проживания, подтверждения платежей и имеющиеся фотографии состояния жилья. Отдельно запишите, какая сумма спорная и чем каждая сторона объясняет свою позицию.',
    'inheritance':'Для подготовки разбора наследства соберите имеющиеся документы о родстве и имуществе, сообщения о других наследниках и сведения о ваших действиях после смерти родственника. Составьте хронологию; неизвестные даты отметьте как неизвестные.',
    'family':'Для подготовки семейного вопроса соберите документы и переписку по спорной ситуации, сведения о договорённостях, платежах и расходах. Отделите подтверждённые обстоятельства от предположений о доходах и намерениях другой стороны.',
    'tax':'Для подготовки налогового разбора сведите в одну таблицу даты, суммы поступлений и расходов и документы, которыми они подтверждаются. Неизвестные значения оставьте отдельными пунктами; общая ориентировка не заменяет проверенный расчёт.',
    'administrative':'Для разбора постановления или штрафа сохраните полный текст полученного документа, сведения о дате и способе получения и доступные материалы события. Отметьте, с какими обстоятельствами вы не согласны. Срок и порядок обжалования здесь не подтверждены.',
    'criminal':'Для подготовки разбора составьте хронологию событий и соберите уже имеющиеся документы, уведомления и сообщения. Отметьте, в какой роли вы участвуете и каких действий от вас ожидают; правовая оценка пока не подтверждена.',
    'procedure':'Для подготовки процессуального вопроса соберите полученные документы целиком и запишите даты их получения, название органа и желаемый результат. Правильная процедура и сроки требуют отдельной проверки.',
}

def general_guidance(base,outcomes):
    tasks=base.get('tasks',[])
    parts=[]
    for task in tasks:
        topic=task['legal_topic'];form=task['formulation'].casefold()
        if topic=='civil' and re.search(r'займ|долг|заем',form):
            text='Для подготовки вопроса о долге сохраните имеющуюся переписку и подтверждения перевода денег. Составьте хронологию: когда передали деньги, о какой сумме и возврате договаривались, какие платежи уже поступили. По этим материалам можно точнее сформулировать вопросы для дальнейшего разбора; взыскание денег здесь не гарантируется.'
        elif topic=='civil' and re.search(r'прод|купл',form):
            text='Для подготовки продажи соберите уже имеющиеся документы об объекте и его приобретении, сведения об участниках и согласованных условиях. Отдельно отметьте, продаётся весь объект или доля и будет ли действовать представитель. Обязательный перечень документов, форма сделки и порядок регистрации пока не подтверждены.'
        else:text=TOPICS.get(topic,COMMON)
        if text not in parts:parts.append(text)
    if not parts:parts.append(COMMON)
    answer='Общая ориентировка — правовой вывод пока не подтверждён.\n\n'+'\n\n'.join(parts)
    answer+='\n\nБолее точный ответ можно получить после проверки применимых материалов и уточнения спорных обстоятельств. Уже сообщённые сведения повторять не нужно.'
    return {**base,'status':'partial_answer','response_kind':'general_guidance','answer':answer,
            'sources':[],'evidence':[],'legal_bases':[],'missing_fields':[],
            'limitations':['Проверка правового ответа не завершена или найденных оснований недостаточно. Это рекомендации по подготовке материалов, а не подтверждение прав, обязанностей, сроков или результата.'],
            'task_outcomes':outcomes}
